insert into questions (id, type, data, status) values ('q_sba_morphine_breastfeeding_001', 'SBA', '{"dateAdded":"2026-09-04","rotationIndex":54,"question":"A 29-year-old woman who is exclusively breastfeeding her infant is recovering from surgery and requires ongoing analgesia. The team is considering the safety of various analgesic options during lactation. Which of the following analgesics carries the greatest concern regarding safety in breastfeeding?","choices":["Morphine","Paracetamol","Ibuprofen","Bupivacaine","Clonidine"],"correct":0,"explanation":"<p>Analgesic choice in breastfeeding mothers must balance maternal pain control against the risk of drug transfer into breast milk and subsequent neonatal exposure, particularly for agents with active metabolites, sedative effects, or accumulation risk in the still-immature neonatal system.</p>\n<p style=\"margin-top:12px\"><strong>A. Correct.</strong> Morphine (and opioids generally) is the analgesic of greatest concern in breastfeeding. While it can be given for breastfeeding women, caution is advised as morphine and its active metabolite (morphine-6-glucuronide) pass into breast milk, and neonates — particularly those under 1 month old — have reduced clearance capacity, increasing the risk of accumulation causing sedation and respiratory depression. Repeated or high-dose maternal opioid use warrants caution and neonatal monitoring; this risk is even more pronounced with codeine in ultra-rapid CYP2D6 metabolisers, but morphine itself still carries meaningful concern, especially in a very young infant.</p>\n<p style=\"margin-top:8px\"><strong>B. Incorrect.</strong> Paracetamol is considered safe in breastfeeding; only minimal amounts are transferred into breast milk, and it lacks significant sedative or respiratory depressant effects on the infant.</p>\n<p style=\"margin-top:8px\"><strong>C. Incorrect.</strong> Ibuprofen is considered the NSAID of choice in breastfeeding due to very low milk transfer, a short half-life, and no significant active metabolites of concern.</p>\n<p style=\"margin-top:8px\"><strong>D. Incorrect.</strong> Bupivacaine is highly protein-bound with minimal systemic absorption and negligible transfer into breast milk when used regionally (e.g. wound catheter, epidural, nerve block); considered safe in breastfeeding.</p>\n<p style=\"margin-top:8px\"><strong>E. Incorrect.</strong> Clonidine can pass into breast milk, and there is some caution advised, but it is generally considered compatible with breastfeeding at low maternal doses with monitoring; it carries substantially less concern than systemic opioids in this context.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Pharmacology Knowledge Summary</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Morphine</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Opioid agonist (mu-receptor)</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic via glucuronidation → active metabolites morphine-6-glucuronide (analgesic, can accumulate in renal impairment) and morphine-3-glucuronide (neuroexcitatory, non-analgesic)</td></tr><tr><td><strong>Milk transfer</strong></td><td>Present in breast milk in clinically relevant amounts; relative infant dose is low-moderate but neonatal clearance is immature, especially &lt;1 month</td></tr><tr><td><strong>Key risk</strong></td><td>Neonatal sedation and respiratory depression, particularly with repeated dosing or in preterm/very young infants</td></tr><tr><td><strong>Practical note</strong></td><td>Short-course, lowest effective dose preferred; monitor infant for sedation, poor feeding, reduced tone</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Paracetamol</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Non-opioid analgesic/antipyretic; exact mechanism incompletely understood — central COX-3 inhibition. May act on the endocannabinoid system via the metabolite AM404, which inhibits reuptake of anandamide, and via descending serotonergic pathways</td></tr><tr><td><strong>Pharmacokinetics</strong></td><td>Rapid absorption; bioavailability 65–85%; protein binding 25%</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic glucuronidation/sulfation; toxic metabolite NAPQI normally detoxified by glutathione (relevant in overdose)</td></tr><tr><td><strong>Milk transfer</strong></td><td>Minimal; considered first-line analgesic in breastfeeding</td></tr><tr><td><strong>Key risk</strong></td><td>Essentially none at therapeutic doses; standard hepatotoxicity risk in maternal overdose only</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Ibuprofen</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Non-selective NSAID (COX-1/COX-2 inhibition)</td></tr><tr><td><strong>Pharmacokinetics</strong></td><td>Highly protein-bound, short half-life (~2 hours)</td></tr><tr><td><strong>Milk transfer</strong></td><td>Very low (&lt;1% of maternal dose); preferred NSAID in lactation by most authorities</td></tr><tr><td><strong>Key risk</strong></td><td>Standard NSAID risks apply to the mother (GI, renal, cardiovascular); negligible infant exposure</td></tr><tr><td><strong>Caution</strong></td><td>Avoid in infants with (or at risk of) reduced renal function; general NSAID caveats around platelet function/bleeding apply to the mother</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Bupivacaine</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Amide local anaesthetic (sodium channel blocker)</td></tr><tr><td><strong>Pharmacokinetics</strong></td><td>Highly protein-bound (~95%); hepatic metabolism via amide hydrolysis (hepatic amidases)</td></tr><tr><td><strong>Milk transfer</strong></td><td>Minimal systemic absorption with regional techniques (wound catheters, epidural, peripheral nerve blocks); negligible milk transfer</td></tr><tr><td><strong>Key risk</strong></td><td>Primarily systemic toxicity (cardiotoxicity/CNS toxicity) at high plasma levels from the maternal procedure itself, not from breastfeeding exposure</td></tr><tr><td><strong>Practical note</strong></td><td>Considered compatible with breastfeeding when used as intended for regional analgesia</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clonidine</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Centrally acting alpha-2 adrenergic agonist</td></tr><tr><td><strong>Uses</strong></td><td>Analgesic adjunct, sedation, and autonomic symptom control (e.g. opioid withdrawal, ADHD)</td></tr><tr><td><strong>Milk transfer</strong></td><td>Detectable in breast milk; some case reports of neonatal sedation/hypotension with higher maternal doses</td></tr><tr><td><strong>Key risk</strong></td><td>Sedation, hypotension, bradycardia in the infant, though generally regarded as compatible with breastfeeding at low doses with monitoring</td></tr><tr><td><strong>Practical note</strong></td><td>Caution advised with maternal doses higher than typical low-dose adjunct use; monitor infant alertness/feeding</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_paeds_crps_school_001', 'SBA', '{"dateAdded":"2026-09-04","rotationIndex":55,"question":"A 12-year-old girl presents 5 months after a well-healed tibial fracture with ongoing signs of complex regional pain syndrome (CRPS) in the affected leg. She has not attended school for 4 months. Her parents report they actively encourage her to rest and avoid school. What is the most appropriate next step in management?","choices":["Involve a paediatrician in her ongoing multidisciplinary care","Make a referral to social services","Tell the parents that what they are doing constitutes abuse","Refer to the GP to make a referral to social services","Perform a lumbar sympathectomy"],"correct":0,"explanation":"<p>This vignette describes a well-recognised pattern in paediatric CRPS: parental reinforcement of rest and avoidance behaviour, though well-intentioned, perpetuates disability, disuse, and functional impairment. This is a psychosocial/behavioural maintaining factor rather than a safeguarding concern or a structural/sympathetically-mediated problem requiring an invasive procedure. Paediatric CRPS management is fundamentally multidisciplinary and function-focused — physiotherapy (graded exposure/desensitisation), psychology, and family/school reintegration — and formal paediatrician involvement is a key, appropriate step to coordinate and oversee this holistic rehabilitative approach given the significant functional impact (4 months out of school).</p>\n<p style=\"margin-top:12px\"><strong>A. Correct.</strong> Paediatric CRPS with major functional impact warrants coordinated paediatric involvement to drive a multidisciplinary rehabilitation plan (physiotherapy, psychology, pain team, school liaison), addressing both the CRPS itself and the family’s maintaining beliefs/behaviours — the most appropriate and proportionate next step among those listed.</p>\n<p style=\"margin-top:8px\"><strong>B. Incorrect.</strong> Not indicated — there is no evidence of neglect, abuse, or safeguarding risk; the parents’ actions stem from misguided protectiveness, not malicious harm, making this disproportionate and likely to damage family engagement.</p>\n<p style=\"margin-top:8px\"><strong>C. Incorrect.</strong> Inaccurate and confrontational; labelling well-intentioned but misguided behaviour as \"abuse\" is unsupported by the vignette and risks alienating the family from future treatment.</p>\n<p style=\"margin-top:8px\"><strong>D. Incorrect.</strong> Shares the same flaw as option B — a safeguarding pathway is not indicated here, regardless of the referral route.</p>\n<p style=\"margin-top:8px\"><strong>E. Incorrect.</strong> An invasive, largely historical intervention with limited evidence base, not indicated as first-line (or even standard) management for paediatric CRPS, and particularly inappropriate before conservative multidisciplinary rehabilitation has been tried; sympathetic blocks/procedures are reserved for select refractory adult cases and are not first-line in children.</p>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_transforaminal_esi_l5_001', 'SBA', '{"dateAdded":"2026-09-04","rotationIndex":56,"question":"A 45-year-old man presents with a 6-week history of severe right leg pain radiating from the buttock to the lateral calf and dorsum of the foot. MRI confirms a right-sided L4/5 disc prolapse causing L5 nerve root compression. What is the most effective next treatment?","choices":["Facet joint injection","Interlaminar epidural steroid injection","Transforaminal epidural steroid injection","Caudal epidural steroid injection","Sciatic nerve block"],"correct":2,"explanation":"<p>Lumbar radicular pain from a disc prolapse compressing a specific nerve root is best treated with an image-guided injection technique that delivers steroid/local anaesthetic as close as possible to the site of pathology — the affected nerve root within or adjacent to the neural foramen — for maximum efficacy.</p>\n<p style=\"margin-top:12px\"><strong>A. Incorrect.</strong> Facet joint injection targets facet-mediated (axial, non-radicular) back pain arising from the zygapophyseal joints; it does not address nerve root compression from a disc prolapse and is not indicated for radicular leg pain.</p>\n<p style=\"margin-top:8px\"><strong>B. Incorrect.</strong> Interlaminar epidural steroid injection delivers steroid into the epidural space more diffusely (typically midline, in the posterior epidural space at or near the level of pathology) rather than targeting the specific compressed nerve root directly, making it less precise and generally considered less effective than a targeted transforaminal approach for single-level radiculopathy.</p>\n<p style=\"margin-top:8px\"><strong>C. Correct.</strong> Transforaminal epidural steroid injection delivers medication directly to the target nerve root (here, L5) at the site of compression/inflammation via the intervertebral foramen, giving it the highest evidence base and greatest efficacy for single-level, unilateral radicular pain from disc prolapse compared to other epidural approaches. It also serves as a good clinical confirmation of pathology site if surgery is being planned.</p>\n<p style=\"margin-top:8px\"><strong>D. Incorrect.</strong> Caudal epidural steroid injection delivers medication via the sacral hiatus, resulting in a more diffuse, lower-concentration spread that may not reliably reach a higher lumbar level (L4/5) in sufficient concentration, making it less targeted/effective than a transforaminal approach for this specific pathology.</p>\n<p style=\"margin-top:8px\"><strong>E. Incorrect.</strong> Sciatic nerve block acts peripherally, distal to the level of pathology; this would produce diagnostically confusing widespread motor/sensory blockade of the entire nerve distribution and does not address the underlying nerve root compression/inflammation, making it inappropriate as a treatment for radiculopathy.</p>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_opioid_renal_copd_fentanyl_001', 'SBA', '{"dateAdded":"2026-09-04","rotationIndex":57,"question":"A patient with severe COPD and renal failure requires opioid analgesia. Which drug is least likely to accumulate in this setting?","choices":["Hydromorphone","Fentanyl","Morphine","Oxycodone","Tramadol"],"correct":1,"explanation":"<p>Opioid selection in renal failure depends heavily on the drug’s metabolic pathway and whether it produces active or toxic metabolites that rely on renal clearance. In a patient with both renal failure and severe COPD, the ideal agent should avoid accumulation (renal safety) while also carrying the lowest risk of exacerbating respiratory depression.</p>\n<p style=\"margin-top:12px\"><strong>A. Incorrect.</strong> Hydromorphone is hepatically metabolised, but its metabolite hydromorphone-3-glucuronide is renally excreted and can accumulate in renal failure, potentially causing neuroexcitatory effects (myoclonus, seizures); caution is needed with dose reduction.</p>\n<p style=\"margin-top:8px\"><strong>B. Correct.</strong> Fentanyl is metabolised hepatically via CYP3A4 to largely inactive metabolites with no clinically significant renally-cleared active metabolites, making it the opioid least likely to accumulate in renal failure. It is generally regarded as one of the safer opioids in renal impairment, though respiratory depression risk from COPD still requires careful titration regardless of drug choice.</p>\n<p style=\"margin-top:8px\"><strong>C. Incorrect.</strong> Morphine is extensively metabolised to morphine-6-glucuronide (active, analgesic/respiratory depressant) and morphine-3-glucuronide (neuroexcitatory); both accumulate significantly in renal failure, making morphine one of the least suitable opioids in this context.</p>\n<p style=\"margin-top:8px\"><strong>D. Incorrect.</strong> Oxycodone is safer than morphine as it is mainly hepatically metabolised to noroxycodone (inactive), but it has a minor active metabolite (oxymorphone) that can accumulate in renal impairment.</p>\n<p style=\"margin-top:8px\"><strong>E. Incorrect.</strong> Tramadol is renally excreted along with its active metabolite (O-desmethyltramadol), which can accumulate in renal failure; it additionally lowers seizure threshold and carries serotonergic risk, making it a poor choice in this context, particularly alongside other CNS-active drugs.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioid Metabolism in Renal Impairment</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Renal safety ranking (most to least favourable):</strong><br>Fentanyl &gt; Oxycodone &asymp; Hydromorphone &gt; Tramadol &gt; Morphine</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Morphine</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via glucuronidation (UGT2B7) — no CYP450 involvement</td></tr><tr><td><strong>Metabolites</strong></td><td>Morphine-6-glucuronide (M6G) — active, potent analgesic and respiratory depressant; morphine-3-glucuronide (M3G) — inactive at opioid receptors but neuroexcitatory (myoclonus, hyperalgesia, seizures)</td></tr><tr><td><strong>Excretion</strong></td><td>Both metabolites renally cleared</td></tr><tr><td><strong>Renal failure implication</strong></td><td>Significant accumulation of both M6G and M3G → prolonged sedation, respiratory depression, and neuroexcitatory toxicity; avoid or use with major dose reduction/extended intervals</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Hydromorphone</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via glucuronidation (UGT) — no clinically significant CYP450 involvement</td></tr><tr><td><strong>Metabolites</strong></td><td>Hydromorphone-3-glucuronide (H3G) — inactive analgesically but neuroexcitatory, similar to M3G</td></tr><tr><td><strong>Excretion</strong></td><td>Renally cleared</td></tr><tr><td><strong>Renal failure implication</strong></td><td>H3G accumulates, risking neuroexcitatory effects (agitation, myoclonus, seizures); caution and dose reduction needed, though generally considered somewhat more favourable than morphine</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Fentanyl</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via CYP3A4 → N-dealkylation to norfentanyl</td></tr><tr><td><strong>Metabolites</strong></td><td>Norfentanyl — inactive</td></tr><tr><td><strong>Excretion</strong></td><td>Metabolites renally excreted but are inactive, so accumulation does not cause clinical effect</td></tr><tr><td><strong>Renal failure implication</strong></td><td>No clinically significant active metabolite accumulation; considered one of the safer opioids in renal impairment; caution still needed regarding accumulation of the parent drug with prolonged infusions (context-sensitive half-time) and with hepatic impairment</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Oxycodone</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via CYP3A4 (major, → noroxycodone, largely inactive) and CYP2D6 (minor, → oxymorphone, active/more potent)</td></tr><tr><td><strong>Metabolites</strong></td><td>Noroxycodone (weakly active), oxymorphone (active)</td></tr><tr><td><strong>Excretion</strong></td><td>Renally cleared</td></tr><tr><td><strong>Renal failure implication</strong></td><td>Parent drug and metabolites can accumulate, prolonging effect; requires dose reduction and caution, though clinically often better tolerated than morphine — CYP2D6 polymorphisms also affect oxymorphone formation and interpatient variability</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tramadol</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via CYP2D6 → O-desmethyltramadol (M1, active metabolite with high mu-affinity, largely responsible for opioid analgesic effect) and CYP3A4 pathways</td></tr><tr><td><strong>Additional mechanism</strong></td><td>Also inhibits serotonin and noradrenaline reuptake (non-opioid analgesic contribution)</td></tr><tr><td><strong>Excretion</strong></td><td>Both parent drug and M1 metabolite renally excreted</td></tr><tr><td><strong>Renal failure implication</strong></td><td>Accumulation of both tramadol and active M1 metabolite; also lowers seizure threshold and carries serotonin syndrome risk (particularly with SSRIs/SNRIs/MAOIs) — caution warranted, especially with polypharmacy</td></tr><tr><td><strong>CYP2D6 variability</strong></td><td>Ultra-rapid metabolisers experience enhanced effect/toxicity risk; poor metabolisers experience reduced analgesic efficacy</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_fentanyl_pca_renal_copd_001', 'SBA', '{"dateAdded":"2026-09-04","rotationIndex":58,"question":"A patient with severe COPD and renal impairment develops severe anterior knee pain following knee surgery, inadequately controlled with simple analgesia. What is the best option for further pain management?","choices":["Fentanyl PCA","Fentanyl boluses","Ketamine infusion 0.1mg/kg/hr","Morphine","Oxycodone"],"correct":0,"explanation":"<p>This patient has two major factors limiting opioid choice: renal impairment (favouring an opioid without active, renally-cleared metabolites) and severe COPD (favouring a delivery method that allows patient-titrated, on-demand dosing to minimise the risk of oversedation and respiratory depression from fixed/nurse-administered boluses).</p>\n<p style=\"margin-top:12px\"><strong>A. Correct.</strong> Fentanyl PCA combines the most renally-favourable opioid (hepatically metabolised to inactive norfentanyl, no significant accumulation in renal impairment) with a delivery method that allows the patient to self-titrate analgesia to their own pain and sedation level, minimising the respiratory depression risk that is particularly dangerous in severe COPD — patient-controlled dosing is inherently safer than fixed boluses since oversedation limits further self-dosing.</p>\n<p style=\"margin-top:8px\"><strong>B. Incorrect.</strong> Fentanyl boluses use the same renally-favourable drug, but as nurse/clinician-administered boluses rather than patient-controlled dosing, this removes the built-in safety ceiling of PCA (the sedated patient simply doesn’t press the button) and is less responsive to the patient’s fluctuating requirements — less optimal than PCA in a high-risk respiratory patient.</p>\n<p style=\"margin-top:8px\"><strong>C. Incorrect.</strong> Ketamine infusion 0.1mg/kg/hr is a useful adjunct in some contexts (e.g. opioid-tolerant patients, opioid-sparing strategies) but is not primarily indicated as first-line monotherapy for severe acute postoperative pain. This would be a rescue option as an add-on if fentanyl PCA fails.</p>\n<p style=\"margin-top:8px\"><strong>D. Incorrect.</strong> Morphine accumulates significantly in renal impairment via active metabolites (M6G, M3G), risking prolonged sedation and respiratory depression — particularly hazardous in a patient with severe COPD.</p>\n<p style=\"margin-top:8px\"><strong>E. Incorrect.</strong> Oxycodone is safer than morphine as it is mainly hepatically metabolised to noroxycodone (inactive), but it has a minor active metabolite (oxymorphone) that can accumulate in renal impairment. An oxycodone PCA would be the correct answer if fentanyl PCA were not in the choices.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Drug Pharmacology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Fentanyl</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>MOA</strong></td><td>Highly selective mu-opioid receptor agonist; highly lipophilic, rapid onset, short context-sensitive half-time with single doses (prolonged with infusions due to fat redistribution)</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via CYP3A4 → N-dealkylation to norfentanyl (inactive)</td></tr><tr><td><strong>Excretion</strong></td><td>Renal excretion of inactive metabolites — no clinically significant accumulation in renal impairment</td></tr><tr><td><strong>Relevance</strong></td><td>Favourable in renal impairment; rapid onset/offset suits PCA titration</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Ketamine</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>MOA</strong></td><td>Non-competitive NMDA receptor antagonist (primary mechanism); also has effects at opioid receptors, monoaminergic reuptake, and voltage-gated calcium/sodium channels. Produces dissociative anaesthesia/analgesia and is a key agent for opioid-sparing and anti-hyperalgesic effect, particularly useful in opioid-tolerant states or central sensitisation</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, primarily via CYP3A4 (and CYP2B6) → norketamine (active, ~1/3–1/5 potency of parent)</td></tr><tr><td><strong>Excretion</strong></td><td>Renal excretion of metabolites</td></tr><tr><td><strong>Relevance</strong></td><td>Psychomimetic side effects (hallucinations, dysphoria) limit use; caution with hepatic impairment; generally low respiratory depressant effect, which can be advantageous in COPD</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Morphine</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>MOA</strong></td><td>Mu-opioid receptor agonist (main), with some kappa activity</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic glucuronidation (UGT2B7, no CYP450 involvement) → morphine-6-glucuronide (M6G, active analgesic/respiratory depressant) and morphine-3-glucuronide (M3G, inactive analgesically but neuroexcitatory)</td></tr><tr><td><strong>Excretion</strong></td><td>Both metabolites renally cleared</td></tr><tr><td><strong>Relevance</strong></td><td>Significant accumulation risk in renal impairment; least favourable of this group for renal/COPD patients</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Oxycodone</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>MOA</strong></td><td>Mu-opioid receptor agonist (with possible minor kappa activity); roughly 1.5x potency of oral morphine</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via CYP3A4 (major → noroxycodone, inactive) and CYP2D6 (minor → oxymorphone, active, more potent)</td></tr><tr><td><strong>Excretion</strong></td><td>Renally cleared parent drug and metabolites</td></tr><tr><td><strong>Relevance</strong></td><td>Accumulates in renal impairment, though often clinically better tolerated than morphine; subject to CYP2D6 genetic variability affecting oxymorphone formation</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_cannabinoid_receptors_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":59,"stem":"Regarding cannabinoid (CB) receptors and their ligands, are the following statements true or false?","choices":["Nabilone is a CB receptor antagonist.","CB2 receptors are mainly located in the central nervous system.","CB2 receptors are inducible and increase in expression during inflammation.","Anandamide can bind to TRPV1 receptors.","Presynaptic CB1 receptors can modulate GABA release."],"correct":[false,false,true,true,true],"explanation":"<p>Cannabinoid receptors (CB1 and CB2) are pre-synaptic G-protein coupled receptors that mediate the effects of endogenous cannabinoids (endocannabinoids, e.g. anandamide, 2-AG) and exogenous cannabinoid drugs, playing important roles in pain modulation, inflammation, and neurotransmission.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — Nabilone is a synthetic cannabinoid and a CB1/CB2 receptor agonist (not antagonist), used clinically for chemotherapy-induced nausea/vomiting and as an adjunct in some chronic pain settings.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — CB1 receptors are the ones predominantly found in the CNS (particularly high density in areas like the hippocampus, cerebellum, and basal ganglia), mediating the classic psychoactive effects of cannabinoids. CB2 receptors are mainly found peripherally, particularly on immune cells (macrophages, microglia, lymphocytes), with comparatively limited CNS expression under normal conditions.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> — CB2 receptor expression is inducible and upregulated during inflammation and tissue injury, particularly on activated microglia and immune cells, which is why CB2 is of particular interest as a target for anti-inflammatory and analgesic drug development without the psychoactive effects associated with CB1.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Anandamide is an endogenous cannabinoid that, in addition to acting at CB1/CB2 receptors, is also an agonist at TRPV1 receptors, contributing to its complex and sometimes dual pro-nociceptive/anti-nociceptive effects depending on the receptor and location involved.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Presynaptic CB1 receptors are widely expressed on both excitatory (glutamatergic) and inhibitory (GABAergic) presynaptic terminals; activation of presynaptic CB1 receptors inhibits neurotransmitter release, including GABA release, forming the basis of \"retrograde endocannabinoid signalling\" in synaptic plasticity.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Cannabinoid System</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"margin-top:18px\"><button type=\"button\" class=\"nice-guideline-btn\" onclick=\"openGuidelineModal(''ng144'',''NG-144 Cannabis Products'')\">\n  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"13\" x2=\"15\" y2=\"13\"/><line x1=\"9\" y1=\"17\" x2=\"15\" y2=\"17\"/></svg>\n  NG-144 Cannabis Products\n</button></div><p style=\"margin:14px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The endocannabinoid system (ECS) is a homeostatic signalling network involved in nociception, mood, appetite, memory, and immune function. It comprises cannabinoid receptors, endogenous ligands (endocannabinoids), and the enzymes that synthesise and degrade them.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Receptors</div><table style=\"margin:0\"><tr><th>Receptor</th><th>Details</th></tr>\n        <tr><td><strong>CB1</strong></td><td>Densely expressed in the CNS (particularly cortex, hippocampus, cerebellum, basal ganglia), with lower peripheral expression. Mediates the psychoactive effects of THC and modulates synaptic neurotransmitter release (both excitatory and inhibitory) via presynaptic inhibition.</td></tr>\n        <tr><td><strong>CB2</strong></td><td>Less ubiquitous; acts by inhibiting proinflammatory responses of immune cells such as macrophages, lymphocytes, and microglia. Largely peripheral/immune in distribution, and upregulated in inflammatory states.</td></tr>\n        <tr><td><strong>Signalling</strong></td><td>Both are G-protein coupled receptors, signalling via inhibition of adenylyl cyclase and reduced cAMP formation.</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Beyond CB1/CB2 — Emerging Targets</div><table style=\"margin:0\"><tr><th>Target</th><th>Details</th></tr>\n        <tr><td><strong>GPR55</strong></td><td>An orphan receptor and its variants have been identified as new endocannabinoid-responsive receptors, sharing numerous cannabinoid ligands with CB1 and CB2, making it a potential therapeutic target for pain.</td></tr>\n        <tr><td><strong>PPARs</strong></td><td>Peroxisome proliferator-activated receptors — nuclear transcription factors activated by cannabinoid-like molecules — have also been implicated in modulating inflammatory and neuropathic pain.</td></tr>\n        <tr><td><strong>TRPV1</strong></td><td>Transient receptor potential channels, most notably TRPV1, have a prominent role in pain and interact with the endocannabinoid system (e.g. anandamide is a TRPV1 agonist as well as a CB1/CB2 ligand).</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Ligands</div><table style=\"margin:0\"><tr><th>Class</th><th>Details</th></tr>\n        <tr><td><strong>Endocannabinoids</strong></td><td>Anandamide and 2-arachidonoylglycerol (2-AG), synthesised on demand from membrane phospholipids, acting as retrograde messengers at presynaptic terminals.</td></tr>\n        <tr><td><strong>Phytocannabinoids</strong></td><td>THC (partial CB1/CB2 agonist, psychoactive) and cannabidiol (CBD, non-psychoactive, complex/indirect pharmacology).</td></tr>\n        <tr><td><strong>Synthetic cannabinoids</strong></td><td>e.g. nabilone (CB1/CB2 agonist, used for chemotherapy-induced nausea/vomiting and occasionally chronic pain).</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Relevance in Pain Medicine</div><table style=\"margin:0\"><tr><th>Point</th><th>Details</th></tr>\n        <tr><td><strong>Preclinical</strong></td><td>Cannabinoids have shown effective anti-nociception in numerous animal models of chronic inflammatory and neuropathic pain, with evidence supporting anti-nociception from dual CB1/CB2 agonists as well as receptor-specific agonists.</td></tr>\n        <tr><td><strong>Clinical evidence</strong></td><td>Human trial evidence is more limited and heterogeneous than preclinical data, particularly for chronic non-cancer pain, with modest effect sizes and significant variability between studies.</td></tr>\n        <tr><td><strong>Direction of travel</strong></td><td>Clinical interest is moving toward peripherally-restricted or receptor-selective agonists to try to separate analgesic benefit from central psychoactive/psychotomimetic side effects.</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_drug_driving_regs_2015_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":60,"stem":"These drugs are specified under the UK Drug Driving Regulations 2015, for which police may test a driver suspected of drug-impaired driving:","choices":["Methadone","Fentanyl","Tramadol","Morphine","Oxycodone"],"correct":[true,false,false,true,false],"explanation":"<p>The Drug Driving (Specified Limits) (England and Wales) Regulations 2015 set defined blood concentration limits for a fixed list of drugs, split into two groups: illicit drugs with very low (\"zero tolerance\"-style) limits (e.g. cannabis, cocaine, ketamine, MDMA, LSD, heroin/6-monoacetylmorphine), and a group of commonly prescribed medicines with higher limits reflecting therapeutic use, including methadone, morphine, diazepam, oxazepam, lorazepam, temazepam, flunitrazepam, and clonazepam. Patients prescribed these drugs are not automatically committing an offence provided their driving is not impaired and, if stopped, they can show the medication was prescribed and taken as directed (a statutory \"medical defence\").</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Methadone has a specified legal limit under this legislation, reflecting its common use in opioid substitution therapy.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Fentanyl is not among the drugs with a specified legal limit under the current regulations, despite being a potent opioid with driving-impairment potential — it is not part of the named list.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Tramadol is not included among the drugs with a specified legal limit under this legislation, despite being commonly prescribed and having sedative/psychomotor effects.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Morphine has a specified legal limit, relevant both to patients on prescribed opioid analgesia and to heroin users (heroin is metabolised to morphine, and 6-monoacetylmorphine — a heroin-specific marker — is separately listed with its own very low limit).</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — Oxycodone is not among the drugs with a specified legal limit under this legislation, despite its widespread prescription for pain.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Controlled Drugs Classification</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Misuse of Drugs Act 1971: Classes A–C</div><table style=\"margin:0\"><tr><th>Class</th><th>Penalty Tier</th><th>Examples Relevant to Pain Medicine</th><th>Other Notable Examples</th></tr>\n        <tr><td><strong>Class A</strong></td><td>Highest harm/penalty</td><td>Morphine, diamorphine (heroin), fentanyl, oxycodone, methadone, ketamine (injectable misuse context varies)</td><td>Cocaine, MDMA, LSD, magic mushrooms</td></tr>\n        <tr><td><strong>Class B</strong></td><td>Intermediate</td><td>Codeine (in unlicensed/high-dose non-medicinal contexts), cannabis, pregabalin, gabapentin</td><td>Amphetamines, barbiturates, synthetic cannabinoids</td></tr>\n        <tr><td><strong>Class C</strong></td><td>Lowest of the three</td><td>Tramadol, benzodiazepines (e.g. diazepam), zolpidem/zopiclone</td><td>Anabolic steroids, GHB</td></tr>\n        </table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Note: Class relates to penalties for unlawful possession/supply, not clinical prescribing rules.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Misuse of Drugs Regulations 2001: Schedules 1–5</div><table style=\"margin:0\"><tr><th>Schedule</th><th>Description</th><th>Prescribing/Storage Requirements</th><th>Examples</th></tr>\n        <tr><td><strong>Schedule 1</strong></td><td>No recognised medicinal use</td><td>Possession/supply generally unlawful except under Home Office licence (research only)</td><td>LSD, raw opium (unprocessed), psilocybin</td></tr>\n        <tr><td><strong>Schedule 2</strong></td><td>Recognised medicinal use, high abuse potential</td><td>Safe custody (locked CD cabinet), CD register entry with running balance, prescription must specify form/strength/dose/total quantity in words and figures</td><td>Morphine, diamorphine, fentanyl, oxycodone, methadone, ketamine, amphetamine</td></tr>\n        <tr><td><strong>Schedule 3</strong></td><td>Recognised medicinal use, lower abuse potential than Sch 2</td><td>CD prescription-writing rules apply (words + figures); most exempt from safe custody (tramadol, midazolam, gabapentin, pregabalin, phenobarbital exempt); no CD register requirement</td><td>Tramadol, midazolam, gabapentin, pregabalin, temazepam, buprenorphine</td></tr>\n        <tr><td><strong>Schedule 4</strong></td><td>Part 1: benzodiazepines; Part 2: anabolic steroids</td><td>No CD prescription-writing requirements; no safe custody; no register</td><td>Diazepam, lorazepam, testosterone</td></tr>\n        <tr><td><strong>Schedule 5</strong></td><td>Very low abuse potential preparations</td><td>Minimal restrictions; can be sold OTC in some cases</td><td>Codeine</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_controlled_drugs_classification_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":61,"stem":"Regarding the classification of these analgesics under UK controlled drug legislation (Misuse of Drugs Act 1971 and Misuse of Drugs Regulations 2001):","choices":["Methadone is a Schedule 2 controlled drug requiring safe custody storage.","Fentanyl is classified as a Class B substance under the Misuse of Drugs Act 1971.","Tramadol is a Schedule 3 controlled drug.","Morphine prescriptions must state the total quantity to be supplied in both words and figures.","Oxycodone is a Schedule 4 controlled drug, in the same schedule as benzodiazepines."],"correct":[true,false,true,true,false],"explanation":"<p>UK controlled drugs are classified in two overlapping systems: the Misuse of Drugs Act 1971 assigns a Class (A, B, C) reflecting perceived harm and penalty tier, while the Misuse of Drugs Regulations 2001 assigns a Schedule (1–5) governing prescribing, storage, and record-keeping requirements.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Methadone is a Schedule 2 controlled drug. Schedule 2 CDs (including morphine, oxycodone, fentanyl, methadone) require secure (safe custody) storage in a CD cabinet and must be recorded in a CD register with a running balance.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Fentanyl is a Class A substance, reflecting its high potency and abuse/harm potential — the same class as morphine, oxycodone, methadone, and diamorphine.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> — Tramadol is a Schedule 3 controlled drug. Unlike most Schedule 3 drugs, tramadol is exempt from the safe custody requirement, though standard CD prescription-writing requirements still apply, and it does not require entry in the CD register.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — For Schedule 2 (and Schedule 3) controlled drugs, UK prescription requirements mandate that the prescriber specify the drug, form, strength, dose, and total quantity in both words and figures, along with being handwritten (or otherwise validated) and dated, to reduce the risk of alteration or diversion.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — Oxycodone is a Schedule 2 controlled drug, not Schedule 4. Schedule 4 contains drugs such as benzodiazepines (Part 1) and anabolic steroids (Part 2), which have a lower CD prescribing/storage burden than Schedule 2 drugs like oxycodone.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Controlled Drugs Classification</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Misuse of Drugs Act 1971: Classes A–C</div><table style=\"margin:0\"><tr><th>Class</th><th>Penalty Tier</th><th>Examples Relevant to Pain Medicine</th><th>Other Notable Examples</th></tr>\n        <tr><td><strong>Class A</strong></td><td>Highest harm/penalty</td><td>Morphine, diamorphine (heroin), fentanyl, oxycodone, methadone, ketamine (injectable misuse context varies)</td><td>Cocaine, MDMA, LSD, magic mushrooms</td></tr>\n        <tr><td><strong>Class B</strong></td><td>Intermediate</td><td>Codeine (in unlicensed/high-dose non-medicinal contexts), cannabis, pregabalin, gabapentin</td><td>Amphetamines, barbiturates, synthetic cannabinoids</td></tr>\n        <tr><td><strong>Class C</strong></td><td>Lowest of the three</td><td>Tramadol, benzodiazepines (e.g. diazepam), zolpidem/zopiclone</td><td>Anabolic steroids, GHB</td></tr>\n        </table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Note: Class relates to penalties for unlawful possession/supply, not clinical prescribing rules.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Misuse of Drugs Regulations 2001: Schedules 1–5</div><table style=\"margin:0\"><tr><th>Schedule</th><th>Description</th><th>Prescribing/Storage Requirements</th><th>Examples</th></tr>\n        <tr><td><strong>Schedule 1</strong></td><td>No recognised medicinal use</td><td>Possession/supply generally unlawful except under Home Office licence (research only)</td><td>LSD, raw opium (unprocessed), psilocybin</td></tr>\n        <tr><td><strong>Schedule 2</strong></td><td>Recognised medicinal use, high abuse potential</td><td>Safe custody (locked CD cabinet), CD register entry with running balance, prescription must specify form/strength/dose/total quantity in words and figures</td><td>Morphine, diamorphine, fentanyl, oxycodone, methadone, ketamine, amphetamine</td></tr>\n        <tr><td><strong>Schedule 3</strong></td><td>Recognised medicinal use, lower abuse potential than Sch 2</td><td>CD prescription-writing rules apply (words + figures); most exempt from safe custody (tramadol, midazolam, gabapentin, pregabalin, phenobarbital exempt); no CD register requirement</td><td>Tramadol, midazolam, gabapentin, pregabalin, temazepam, buprenorphine</td></tr>\n        <tr><td><strong>Schedule 4</strong></td><td>Part 1: benzodiazepines; Part 2: anabolic steroids</td><td>No CD prescription-writing requirements; no safe custody; no register</td><td>Diazepam, lorazepam, testosterone</td></tr>\n        <tr><td><strong>Schedule 5</strong></td><td>Very low abuse potential preparations</td><td>Minimal restrictions; can be sold OTC in some cases</td><td>Codeine</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_opioid_qtc_prolongation_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":62,"stem":"Which of these prolong QTc?","choices":["Hydromorphone","Tapentadol","Pethidine","Methadone","Alfentanil"],"correct":[false,false,false,true,false],"explanation":"<p>QTc prolongation is a clinically important consideration in opioid prescribing, as it increases the risk of torsades de pointes and sudden cardiac death; the risk varies markedly between opioids depending on their effect on cardiac potassium channels (hERG channel blockade), and this variability is a well-recognised exam theme.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> — Hydromorphone is not significantly associated with clinically relevant QTc prolongation and is considered one of the safer opioid choices where QTc prolongation is a concern.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Tapentadol has not been shown to cause clinically significant QTc prolongation at therapeutic doses, unlike some other opioids.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Pethidine is not classically associated with QTc prolongation as its primary cardiac concern; its more notable risks relate to its metabolite norpethidine (neuroexcitatory, seizure risk in accumulation) and serotonergic interactions (serotonin syndrome risk with MAOIs/SSRIs), rather than QTc effects.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Methadone is the opioid most strongly and consistently associated with dose-dependent QTc prolongation, via direct blockade of the cardiac hERG potassium channel. This is a well-established risk requiring baseline and periodic ECG monitoring, particularly at higher doses, with other risk factors (electrolyte disturbance, other QT-prolonging drugs), or with rapid dose escalation.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — Alfentanil is not significantly associated with QTc prolongation and is generally considered cardiac-safe in this respect, consistent with other fentanyl-derivative opioids.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioid Pharmacology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Hydromorphone</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Semi-synthetic mu-opioid receptor agonist; ~5–7x potency of oral morphine</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic glucuronidation (UGT) → hydromorphone-3-glucuronide (H3G, inactive analgesically, neuroexcitatory) — no significant CYP450 involvement</td></tr><tr><td><strong>Excretion</strong></td><td>Renal</td></tr><tr><td><strong>Cardiac</strong></td><td>No significant QTc effect</td></tr><tr><td><strong>Notable features</strong></td><td>Useful alternative to morphine in mild-moderate renal impairment (though H3G still accumulates, requiring caution); available in high-concentration formulations useful in palliative care for small-volume dosing</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tapentadol</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Dual-mechanism analgesic — mu-opioid receptor agonist and noradrenaline reuptake inhibitor (NRI); minimal serotonergic activity, distinguishing it from tramadol</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, primarily glucuronidation (UGT) — minimal CYP450 involvement, few active metabolites</td></tr><tr><td><strong>Excretion</strong></td><td>Renal</td></tr><tr><td><strong>Cardiac</strong></td><td>No significant QTc effect</td></tr><tr><td><strong>Notable features</strong></td><td>Lower incidence of nausea/vomiting and constipation than classical opioids at equianalgesic doses, attributed to lower mu-receptor occupancy for equivalent analgesia; lower serotonin syndrome risk than tramadol due to minimal serotonergic activity; used in both acute nociceptive and neuropathic pain</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pethidine (Meperidine)</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Synthetic mu-opioid receptor agonist with additional local anaesthetic-like (sodium channel blocking) and anticholinergic/antimuscarinic properties</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via N-demethylation → norpethidine, an active, neuroexcitatory metabolite (lowers seizure threshold, causes tremor/myoclonus/agitation) that accumulates with repeated dosing or renal impairment</td></tr><tr><td><strong>Excretion</strong></td><td>Renal (norpethidine notably renally cleared and accumulates in renal impairment)</td></tr><tr><td><strong>Cardiac</strong></td><td>Not classically associated with QTc prolongation</td></tr><tr><td><strong>Notable features</strong></td><td>Significant serotonergic activity — contraindicated with MAOIs (risk of severe serotonin syndrome/hyperpyrexic reactions); historically used in labour analgesia, now largely superseded due to norpethidine toxicity risk and neonatal effects</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Methadone</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Synthetic mu-opioid receptor agonist and NMDA receptor antagonist; also inhibits monoamine (serotonin/noradrenaline) reuptake</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, primarily via CYP3A4 (also CYP2B6, CYP2D6) → inactive metabolites; highly variable interpatient pharmacokinetics</td></tr><tr><td><strong>Excretion</strong></td><td>Faecal/biliary predominant (advantageous in renal impairment) with a minor renal component</td></tr><tr><td><strong>Pharmacokinetics</strong></td><td>Long and highly variable half-life (8–60+ hours), poor correlation between plasma level and effect, risk of delayed accumulation/toxicity with dose titration</td></tr><tr><td><strong>Cardiac</strong></td><td><strong>Most significant opioid cause of dose-dependent QTc prolongation</strong> via hERG potassium channel blockade — requires baseline/periodic ECG monitoring, particularly at higher doses or with other risk factors</td></tr><tr><td><strong>Notable features</strong></td><td>NMDA antagonism provides additional utility in neuropathic pain and opioid tolerance/hyperalgesia; complex drug interactions via CYP3A4 (many drugs alter methadone levels)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Alfentanil</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td><strong>Class</strong></td><td>Highly selective mu-opioid receptor agonist; synthetic fentanyl analogue</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic, via CYP3A4 → inactive metabolites</td></tr><tr><td><strong>Excretion</strong></td><td>Renal (inactive metabolites — no clinically significant accumulation in renal impairment)</td></tr><tr><td><strong>Pharmacokinetics</strong></td><td>Rapid onset, short duration of action due to small volume of distribution and rapid redistribution/clearance — shortest context-sensitive half-time of the fentanyl-family opioids, making it useful for short procedures</td></tr><tr><td><strong>Cardiac</strong></td><td>No significant QTc effect</td></tr><tr><td><strong>Notable features</strong></td><td>Primarily used intraoperatively/for short procedures rather than chronic pain management; potency roughly 1/4–1/10 that of fentanyl but faster onset/offset</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_stellate_ganglion_consent_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":63,"stem":"Which complications should be discussed at consent for a stellate ganglion block?","choices":["Pneumothorax","Constipation","Gastroparesis","Hypertension","Hoarseness of voice"],"correct":[true,false,false,false,true],"explanation":"<p>The stellate ganglion (cervicothoracic sympathetic ganglion) lies close to several important structures at the base of the neck, and consent should cover both common minor side effects (expected sympathetic blockade features) and rarer but serious procedural risks related to needle trajectory and local spread of injectate.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Pneumothorax is a recognised risk due to the close proximity of the lung apex to the injection target, particularly with a lower (anterior C7) approach; careful needle depth control and image guidance reduce but do not eliminate this risk.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Constipation is not a recognised complication of stellate ganglion block; it has no established mechanism of action on gut motility relevant to this procedure.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Gastroparesis is not a recognised complication of stellate ganglion block; this is not an expected effect of cervical sympathetic blockade.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> — Sympathetic blockade from a stellate ganglion block causes vasodilation in the blocked territory, and hypotension (not hypertension) is the more relevant/recognised haemodynamic consideration, alongside the expected localised effects of Horner’s syndrome (ptosis, miosis, anhidrosis) from sympathetic interruption to the head/neck/upper limb.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Hoarseness of voice is a recognised risk due to local spread of anaesthetic to the recurrent laryngeal nerve, which runs close to the injection site; this is usually transient but should be specifically consented for, along with the associated risk of subjective dysphagia/risk of aspiration while the effect lasts.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Stellate Ganglion</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy Background</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The stellate ganglion is formed by fusion of the inferior cervical and first thoracic sympathetic ganglia (present in ~80% of people; when unfused, only the inferior cervical ganglion is blocked). It lies anterior to the neck of the first rib and the transverse process of C7, close to the vertebral artery, longus colli muscle, carotid sheath, recurrent laryngeal nerve, and lung apex — most anaesthetists target the C6 (Chassaignac''s tubercle) level anteriorly to reduce pneumothorax/vertebral artery injection risk while still achieving adequate spread to block the ganglion at C7/T1.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications</div><table style=\"margin:0\"><tr><th>Category</th><th>Examples</th></tr>\n        <tr><td><strong>Sympathetically-maintained pain</strong></td><td>Complex regional pain syndrome (CRPS) of the upper limb; post-herpetic neuralgia (head, neck, upper limb distribution); phantom limb pain (upper limb); refractory angina (adjunctive)</td></tr>\n        <tr><td><strong>Vascular</strong></td><td>Raynaud''s phenomenon/peripheral vascular insufficiency of the upper limb; vasospastic disorders, upper limb ischaemia; post-traumatic vasospasm, frostbite</td></tr>\n        <tr><td><strong>Other</strong></td><td>Hyperhidrosis (upper limb/facial); refractory ventricular arrhythmias/electrical storm (cardiac sympathetic denervation); some vasomotor symptom indications (e.g. menopausal hot flushes) — emerging/off-label; PTSD (emerging, off-label, investigational)</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Contraindications</div><table style=\"margin:0\"><tr><th>Type</th><th>Examples</th></tr>\n        <tr><td><strong>Absolute</strong></td><td>Patient refusal/inability to consent; local infection at injection site; coagulopathy/significant bleeding diathesis (relative-absolute depending on severity, given proximity to major vessels); recent MI or uncontrolled cardiac arrhythmia; contralateral phrenic nerve palsy or contralateral pneumothorax; contralateral recurrent laryngeal nerve palsy</td></tr>\n        <tr><td><strong>Relative</strong></td><td>Severe respiratory disease/compromised pulmonary reserve; glaucoma (Horner''s syndrome effects); allergy to local anaesthetic; anticoagulation (per standard regional anaesthesia guidance on interruption)</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Complications</div><table style=\"margin:0\"><tr><th>Category</th><th>Details</th></tr>\n        <tr><td><strong>Expected/anticipated</strong></td><td>Horner''s syndrome (ptosis, miosis, anhidrosis, enophthalmos) — confirms successful block; nasal congestion (Guttman''s sign); conjunctival injection; temperature/colour change and increased skin temperature in the blocked limb</td></tr>\n        <tr><td><strong>Recognised complications</strong></td><td>Hoarseness of voice (recurrent laryngeal nerve, usually transient); dysphagia; pneumothorax (lung apex proximity); haematoma (vascular puncture); intravascular injection (especially vertebral artery — seizure/LOC even with tiny volumes); intrathecal/epidural spread (high or total spinal); brachial plexus block (spread too lateral/posterior); phrenic nerve block (hemidiaphragmatic paresis); infection; bradycardia (cardiac accelerator fibre blockade)</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_stellate_ganglion_c6_us_anatomy_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":64,"stem":"Regarding stellate ganglion block at C6 using ultrasound:","choices":["The target injection point lies anterior to longus colli muscle.","The carotid sheath lies posterior to the target injection point.","The oesophagus lies medial to the target injection point.","The thoracic duct lies medial to the target injection point.","The dome of the lung lies inferior to the target injection point."],"correct":[true,false,true,true,true],"explanation":"<p>Ultrasound-guided stellate ganglion block is typically performed at the C6 level (Chassaignac''s tubercle), where injectate is deposited into the fascial plane between the prevertebral fascia and longus colli muscle, allowing spread down to the stellate ganglion at C7/T1 while avoiding a deeper, riskier approach directly at C7.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — The injection target is the fascial plane anterior to longus colli muscle, deep to the carotid sheath and sternocleidomastoid, allowing safe deposition of local anaesthetic away from the vertebral artery (which runs within the transverse foramen, posterior to longus colli).</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — The carotid sheath (containing the carotid artery, internal jugular vein, and vagus nerve) lies lateral to the target injection point, not posterior. On ultrasound, the sheath and its contents are identified and retracted/avoided laterally before advancing the needle to the prevertebral fascia/longus colli plane.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> — The oesophagus lies medial to the target, tucked between the trachea and prevertebral fascia; it is of particular relevance on the left side, where the oesophagus can deviate further leftward, increasing the risk of inadvertent puncture or injection with a left-sided block.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — The thoracic duct lies medially and inferiorly, entering the venous system near the junction of the left subclavian and internal jugular veins; it is a specifically recognised risk structure for left-sided stellate ganglion blocks, with chylothorax a rare reported complication.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — The dome (apex) of the lung lies inferior to the C6-level injection site, which is part of the rationale for performing the block at C6 rather than lower at C7 — reducing (though not eliminating) the risk of pneumothorax.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Stellate Ganglion</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px\">\n        <div style=\"position:relative;width:100%;padding-top:56.25%;border-radius:10px;overflow:hidden;background:#000\">\n          <iframe src=\"https://www.youtube.com/embed/B6ROeVFUJSY\" title=\"Stellate Ganglion Block\" style=\"position:absolute;inset:0;width:100%;height:100%;border:0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>\n        </div>\n      </div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_ketamine_general_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":65,"stem":"Ketamine:","choices":["Ketamine is available clinically as a racemic mixture of S and R isomers.","Chronic ketamine use is associated with toxicity to the urinary tract.","The R(-) isomer of ketamine is more potent than the S(+) isomer.","The S(+) isomer is associated with greater psychomimetic effects than the R(-) isomer.","Ketamine has local anaesthetic-like effects via blockade of voltage-gated sodium channels."],"correct":[true,true,false,true,true],"explanation":"<p>Ketamine is a phencyclidine derivative, primarily known for NMDA receptor antagonism producing dissociative anaesthesia and analgesia, though it has several other receptor and channel interactions contributing to its overall clinical effect.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Standard clinical ketamine preparations are a racemic mixture of the S(+) and R(-) enantiomers; a single-isomer S(+)-ketamine (esketamine) preparation is also available separately, roughly twice as potent as the racemate.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — Chronic/heavy ketamine use is well recognised to cause urinary tract toxicity, specifically \"ketamine-induced ulcerative cystitis,\" causing severe lower urinary tract symptoms (frequency, urgency, dysuria, haematuria), reduced bladder capacity, and in severe cases hydronephrosis and renal impairment secondary to bladder pathology.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — It is the S(+) isomer, not R(-), that is more potent — the S(+) isomer has higher affinity for the NMDA receptor and is approximately 2–4 times more potent as an analgesic/anaesthetic than the R(-) isomer.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — The S(+) isomer has greater psychomimetic activity than the R(-) isomer.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — In addition to its principal NMDA receptor antagonism, ketamine also has local anaesthetic-like properties via blockade of voltage-gated sodium channels, contributing to its analgesic effect and providing a pharmacological basis for its occasional use (typically at higher/local concentrations) in modulating neuronal excitability beyond the NMDA pathway alone; ketamine also interacts with opioid receptors, monoaminergic reuptake, and voltage-gated calcium channels, reflecting its broad multimodal pharmacology.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Ketamine Pharmacology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification & Structure</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Class</strong></td><td>Phencyclidine (PCP) derivative, arylcyclohexylamine</td></tr>\n        <tr><td><strong>Stereochemistry</strong></td><td>Chiral molecule with one stereocentre → two enantiomers (S(+) and R(-)), not geometric isomers</td></tr>\n        <tr><td><strong>Clinical preparations</strong></td><td>Racemic mixture (50:50 S:R) is standard; single-isomer S(+)-ketamine (esketamine) also available, ~2x more potent than the racemate</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mechanism of Action</div><table style=\"margin:0\"><tr><th>Target</th><th>Detail</th></tr>\n        <tr><td><strong>Primary</strong></td><td>Non-competitive (use-dependent, open-channel blocking) antagonist at the NMDA receptor, binding within the channel pore rather than the glutamate binding site</td></tr>\n        <tr><td><strong>Muscarinic ACh receptors</strong></td><td>Antagonist</td></tr>\n        <tr><td><strong>Nicotinic ACh receptors</strong></td><td>Inhibitor</td></tr>\n        <tr><td><strong>Opioid receptors</strong></td><td>Weak agonist activity — mu, kappa, sigma sites implicated</td></tr>\n        <tr><td><strong>Voltage-gated sodium channels</strong></td><td>Local anaesthetic-like membrane-stabilising effect (NOT potassium channels)</td></tr>\n        <tr><td><strong>Monoaminergic reuptake</strong></td><td>Inhibition (noradrenaline, serotonin) — central sympathomimetic basis</td></tr>\n        <tr><td><strong>Isomer differences</strong></td><td>S(+) has higher NMDA affinity and is more potent than R(-); S(+) is associated with greater psychomimetic/hallucinogenic effects; R(-) is better tolerated psychologically and of research interest (e.g. depression) for separating benefit from dissociative side effects</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cardiovascular Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Dominant effect</strong></td><td>Central sympathetic stimulation (inhibits catecholamine reuptake) → increased HR, BP, cardiac output</td></tr>\n        <tr><td><strong>Masked effect</strong></td><td>Also has a direct myocardial depressant effect, normally masked by sympathetic stimulation; unmasked in catecholamine-depleted states (critical illness, sepsis) → unexpected hypotension/reduced contractility</td></tr>\n        <tr><td><strong>QTc</strong></td><td>No significant QTc prolongation</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Respiratory Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Airway/drive</strong></td><td>Relative preservation of airway reflexes and respiratory drive compared to other anaesthetic agents</td></tr>\n        <tr><td><strong>Bronchodilation</strong></td><td>Useful in refractory status asthmaticus (via sympathomimetic + direct bronchial smooth muscle relaxation); no established isomer-specific superiority</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CNS/Neurological Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Cerebral metabolism</strong></td><td>S(+) ketamine reduces cerebral metabolic rate while preserving cerebrovascular autoregulation and CO2 reactivity (revising older teaching that ketamine universally raises ICP)</td></tr>\n        <tr><td><strong>Seizures/epilepsy</strong></td><td>Does not reliably trigger clinical seizures; used in refractory status epilepticus; not contraindicated in epilepsy</td></tr>\n        <tr><td><strong>Neuroprotection</strong></td><td>Possible neuroprotective/neuroregenerative effects — proposed mechanism is <em>reduction</em> (not increase) of excitotoxic calcium influx/glutamate activity via NMDA blockade; also implicated in synaptogenesis (BDNF/mTOR pathway — relevant to depression research)</td></tr>\n        <tr><td><strong>Clinical effects</strong></td><td>Causes dissociative anaesthesia, emergence phenomena (hallucinations, vivid dreams), nystagmus</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Renal/Urinary Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Renal failure</strong></td><td>Not contraindicated in chronic renal failure — metabolites are not a major clinical concern (unlike morphine/pethidine)</td></tr>\n        <tr><td><strong>Chronic/heavy use</strong></td><td>Causes ketamine-induced ulcerative cystitis — urinary frequency, urgency, dysuria, haematuria, reduced bladder capacity, and in severe cases hydronephrosis/renal impairment</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Immune Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Immunomodulation</strong></td><td>Anti-inflammatory properties — attenuates pro-inflammatory cytokine release (TNF-alpha, IL-6); relevance to sepsis and perioperative inflammatory response is an active research area</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Metabolism</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Pathway</strong></td><td>Hepatic, primarily via CYP3A4 (and CYP2B6) → norketamine (active metabolite, ~1/3–1/5 potency of parent)</td></tr>\n        <tr><td><strong>Excretion</strong></td><td>Renal excretion of metabolites</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_ketamine_isomer_potency_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":66,"stem":"Regarding ketamine, are the following statements true or false?","choices":["It acts on the central nervous system.","It has local anaesthetic properties.","S(+) ketamine is four times as potent as the racemate.","S(+) ketamine and R(-) ketamine have the same affinity for NMDA receptors.","Ketamine has two geometric isomers."],"correct":[true,true,false,false,false],"explanation":"<p>Ketamine is a phencyclidine derivative acting primarily as a non-competitive NMDA receptor antagonist, producing dissociative anaesthesia, analgesia, and a range of other CNS and peripheral effects, alongside a distinct pharmacokinetic and isomer-specific profile.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Ketamine acts centrally, principally via NMDA receptor antagonism in the CNS, producing its characteristic dissociative anaesthetic, analgesic, amnesic, and psychomimetic effects; it also has effects at opioid, monoaminergic, and muscarinic receptors within the CNS.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — Ketamine has local anaesthetic-like properties via blockade of voltage-gated sodium channels, contributing an additional analgesic mechanism beyond its central NMDA antagonism.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — S(+) ketamine is approximately twice as potent as the racemate (not four times), reflecting that the racemate is a 50:50 mix of the more potent S(+) and less potent R(-) isomers — S(+) alone therefore has roughly double the potency of the mixed preparation.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> — S(+) and R(-) ketamine do not have the same NMDA receptor affinity — S(+) ketamine has a higher affinity for the NMDA receptor (and is more potent) than R(-) ketamine, which underlies the difference in their clinical potency and side-effect profiles.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — Ketamine''s S(+) and R(-) forms are enantiomers (optical/stereoisomers), arising from a single chiral centre, not geometric (cis-trans) isomers — geometric isomerism requires restricted rotation (e.g. around a double bond or ring), which is not the basis of ketamine''s isomerism.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Ketamine Pharmacology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification & Structure</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Class</strong></td><td>Phencyclidine (PCP) derivative, arylcyclohexylamine</td></tr>\n        <tr><td><strong>Stereochemistry</strong></td><td>Chiral molecule with one stereocentre → two enantiomers (S(+) and R(-)), not geometric isomers</td></tr>\n        <tr><td><strong>Clinical preparations</strong></td><td>Racemic mixture (50:50 S:R) is standard; single-isomer S(+)-ketamine (esketamine) also available, ~2x more potent than the racemate</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mechanism of Action</div><table style=\"margin:0\"><tr><th>Target</th><th>Detail</th></tr>\n        <tr><td><strong>Primary</strong></td><td>Non-competitive (use-dependent, open-channel blocking) antagonist at the NMDA receptor, binding within the channel pore rather than the glutamate binding site</td></tr>\n        <tr><td><strong>Muscarinic ACh receptors</strong></td><td>Antagonist</td></tr>\n        <tr><td><strong>Nicotinic ACh receptors</strong></td><td>Inhibitor</td></tr>\n        <tr><td><strong>Opioid receptors</strong></td><td>Weak agonist activity — mu, kappa, sigma sites implicated</td></tr>\n        <tr><td><strong>Voltage-gated sodium channels</strong></td><td>Local anaesthetic-like membrane-stabilising effect (NOT potassium channels)</td></tr>\n        <tr><td><strong>Monoaminergic reuptake</strong></td><td>Inhibition (noradrenaline, serotonin) — central sympathomimetic basis</td></tr>\n        <tr><td><strong>Isomer differences</strong></td><td>S(+) has higher NMDA affinity and is more potent than R(-); S(+) is associated with greater psychomimetic/hallucinogenic effects; R(-) is better tolerated psychologically and of research interest (e.g. depression) for separating benefit from dissociative side effects</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cardiovascular Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Dominant effect</strong></td><td>Central sympathetic stimulation (inhibits catecholamine reuptake) → increased HR, BP, cardiac output</td></tr>\n        <tr><td><strong>Masked effect</strong></td><td>Also has a direct myocardial depressant effect, normally masked by sympathetic stimulation; unmasked in catecholamine-depleted states (critical illness, sepsis) → unexpected hypotension/reduced contractility</td></tr>\n        <tr><td><strong>QTc</strong></td><td>No significant QTc prolongation</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Respiratory Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Airway/drive</strong></td><td>Relative preservation of airway reflexes and respiratory drive compared to other anaesthetic agents</td></tr>\n        <tr><td><strong>Bronchodilation</strong></td><td>Useful in refractory status asthmaticus (via sympathomimetic + direct bronchial smooth muscle relaxation); no established isomer-specific superiority</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CNS/Neurological Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Cerebral metabolism</strong></td><td>S(+) ketamine reduces cerebral metabolic rate while preserving cerebrovascular autoregulation and CO2 reactivity (revising older teaching that ketamine universally raises ICP)</td></tr>\n        <tr><td><strong>Seizures/epilepsy</strong></td><td>Does not reliably trigger clinical seizures; used in refractory status epilepticus; not contraindicated in epilepsy</td></tr>\n        <tr><td><strong>Neuroprotection</strong></td><td>Possible neuroprotective/neuroregenerative effects — proposed mechanism is <em>reduction</em> (not increase) of excitotoxic calcium influx/glutamate activity via NMDA blockade; also implicated in synaptogenesis (BDNF/mTOR pathway — relevant to depression research)</td></tr>\n        <tr><td><strong>Clinical effects</strong></td><td>Causes dissociative anaesthesia, emergence phenomena (hallucinations, vivid dreams), nystagmus</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Renal/Urinary Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Renal failure</strong></td><td>Not contraindicated in chronic renal failure — metabolites are not a major clinical concern (unlike morphine/pethidine)</td></tr>\n        <tr><td><strong>Chronic/heavy use</strong></td><td>Causes ketamine-induced ulcerative cystitis — urinary frequency, urgency, dysuria, haematuria, reduced bladder capacity, and in severe cases hydronephrosis/renal impairment</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Immune Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Immunomodulation</strong></td><td>Anti-inflammatory properties — attenuates pro-inflammatory cytokine release (TNF-alpha, IL-6); relevance to sepsis and perioperative inflammatory response is an active research area</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Metabolism</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Pathway</strong></td><td>Hepatic, primarily via CYP3A4 (and CYP2B6) → norketamine (active metabolite, ~1/3–1/5 potency of parent)</td></tr>\n        <tr><td><strong>Excretion</strong></td><td>Renal excretion of metabolites</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_ketamine_receptor_binding_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":67,"stem":"Ketamine binds to:","choices":["NMDA receptors.","Muscarinic receptors.","Nicotinic receptors.","Opioid receptors.","Neuronal potassium channels, to exhibit its local anaesthetic properties."],"correct":[true,true,true,true,false],"explanation":"<p>Ketamine has a broad receptor and channel interaction profile beyond its principal NMDA antagonism, which underlies much of its diverse clinical effect and side-effect spectrum.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Ketamine''s principal mechanism is non-competitive antagonism at the NMDA receptor, binding within the open ion channel pore, underlying its dissociative anaesthetic and analgesic effects.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> — Ketamine has affinity for muscarinic acetylcholine receptors (antagonist activity), contributing to some of its anticholinergic-type effects and possibly its emergence phenomena/delirium profile.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> — Ketamine also inhibits nicotinic acetylcholine receptors, adding to its broad receptor interaction profile beyond the NMDA system.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Ketamine has weak affinity at opioid receptors (mu, kappa, and sigma sites have all been implicated), contributing modestly to its overall analgesic effect alongside NMDA antagonism.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — Ketamine''s local anaesthetic-like properties arise from blockade of voltage-gated sodium channels, not potassium channels — this sodium channel effect underlies its use-dependent membrane-stabilising action, contributing an additional analgesic mechanism distinct from NMDA antagonism.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Ketamine Pharmacology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification & Structure</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Class</strong></td><td>Phencyclidine (PCP) derivative, arylcyclohexylamine</td></tr>\n        <tr><td><strong>Stereochemistry</strong></td><td>Chiral molecule with one stereocentre → two enantiomers (S(+) and R(-)), not geometric isomers</td></tr>\n        <tr><td><strong>Clinical preparations</strong></td><td>Racemic mixture (50:50 S:R) is standard; single-isomer S(+)-ketamine (esketamine) also available, ~2x more potent than the racemate</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mechanism of Action</div><table style=\"margin:0\"><tr><th>Target</th><th>Detail</th></tr>\n        <tr><td><strong>Primary</strong></td><td>Non-competitive (use-dependent, open-channel blocking) antagonist at the NMDA receptor, binding within the channel pore rather than the glutamate binding site</td></tr>\n        <tr><td><strong>Muscarinic ACh receptors</strong></td><td>Antagonist</td></tr>\n        <tr><td><strong>Nicotinic ACh receptors</strong></td><td>Inhibitor</td></tr>\n        <tr><td><strong>Opioid receptors</strong></td><td>Weak agonist activity — mu, kappa, sigma sites implicated</td></tr>\n        <tr><td><strong>Voltage-gated sodium channels</strong></td><td>Local anaesthetic-like membrane-stabilising effect (NOT potassium channels)</td></tr>\n        <tr><td><strong>Monoaminergic reuptake</strong></td><td>Inhibition (noradrenaline, serotonin) — central sympathomimetic basis</td></tr>\n        <tr><td><strong>Isomer differences</strong></td><td>S(+) has higher NMDA affinity and is more potent than R(-); S(+) is associated with greater psychomimetic/hallucinogenic effects; R(-) is better tolerated psychologically and of research interest (e.g. depression) for separating benefit from dissociative side effects</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cardiovascular Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Dominant effect</strong></td><td>Central sympathetic stimulation (inhibits catecholamine reuptake) → increased HR, BP, cardiac output</td></tr>\n        <tr><td><strong>Masked effect</strong></td><td>Also has a direct myocardial depressant effect, normally masked by sympathetic stimulation; unmasked in catecholamine-depleted states (critical illness, sepsis) → unexpected hypotension/reduced contractility</td></tr>\n        <tr><td><strong>QTc</strong></td><td>No significant QTc prolongation</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Respiratory Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Airway/drive</strong></td><td>Relative preservation of airway reflexes and respiratory drive compared to other anaesthetic agents</td></tr>\n        <tr><td><strong>Bronchodilation</strong></td><td>Useful in refractory status asthmaticus (via sympathomimetic + direct bronchial smooth muscle relaxation); no established isomer-specific superiority</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CNS/Neurological Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Cerebral metabolism</strong></td><td>S(+) ketamine reduces cerebral metabolic rate while preserving cerebrovascular autoregulation and CO2 reactivity (revising older teaching that ketamine universally raises ICP)</td></tr>\n        <tr><td><strong>Seizures/epilepsy</strong></td><td>Does not reliably trigger clinical seizures; used in refractory status epilepticus; not contraindicated in epilepsy</td></tr>\n        <tr><td><strong>Neuroprotection</strong></td><td>Possible neuroprotective/neuroregenerative effects — proposed mechanism is <em>reduction</em> (not increase) of excitotoxic calcium influx/glutamate activity via NMDA blockade; also implicated in synaptogenesis (BDNF/mTOR pathway — relevant to depression research)</td></tr>\n        <tr><td><strong>Clinical effects</strong></td><td>Causes dissociative anaesthesia, emergence phenomena (hallucinations, vivid dreams), nystagmus</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Renal/Urinary Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Renal failure</strong></td><td>Not contraindicated in chronic renal failure — metabolites are not a major clinical concern (unlike morphine/pethidine)</td></tr>\n        <tr><td><strong>Chronic/heavy use</strong></td><td>Causes ketamine-induced ulcerative cystitis — urinary frequency, urgency, dysuria, haematuria, reduced bladder capacity, and in severe cases hydronephrosis/renal impairment</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Immune Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Immunomodulation</strong></td><td>Anti-inflammatory properties — attenuates pro-inflammatory cytokine release (TNF-alpha, IL-6); relevance to sepsis and perioperative inflammatory response is an active research area</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Metabolism</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Pathway</strong></td><td>Hepatic, primarily via CYP3A4 (and CYP2B6) → norketamine (active metabolite, ~1/3–1/5 potency of parent)</td></tr>\n        <tr><td><strong>Excretion</strong></td><td>Renal excretion of metabolites</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_ketamine_neurological_effects_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":68,"stem":"Ketamine:","choices":["S(+) ketamine reduces cerebral metabolism and maintains cerebrovascular autoregulation.","Ketamine triggers seizure activity.","Ketamine is contraindicated in patients with epilepsy.","Ketamine may have neuroprotective and neuroregenerative effects.","Neuroprotection appears to be due to increased calcium fluxes and glutamate accumulation at the NMDA receptor."],"correct":[true,false,false,true,false],"explanation":"<p>Ketamine''s neurological effects have been historically over-simplified and misunderstood — older teaching emphasised raised intracranial pressure and epileptogenic risk, but more recent evidence has substantially revised this view, particularly for the S(+) isomer.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — S(+) ketamine, unlike the racemate at higher doses, has been shown to reduce cerebral metabolic rate while preserving cerebrovascular autoregulation and CO2 reactivity, challenging the older dogma that all ketamine formulations uniformly raise cerebral metabolism and intracranial pressure.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Ketamine does not reliably trigger clinical seizure activity. While it can produce excitatory EEG changes (particularly in limbic structures) at a neurophysiological level, this does not translate into a clinically significant proconvulsant effect, and ketamine is in fact used as a treatment option in refractory status epilepticus.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — Ketamine is not contraindicated in patients with epilepsy. Given its use in treating refractory status epilepticus and lack of reliable proconvulsant clinical effect, it can be used cautiously in this population, in contrast to older teaching that avoided ketamine in epilepsy.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> — Ketamine may have neuroprotective and neuroregenerative effects, an area of active research interest — proposed mechanisms include reduction of excitotoxic injury via NMDA antagonism, anti-inflammatory effects, and (in psychiatric/depression research) promotion of synaptogenesis via downstream BDNF/mTOR pathway activation.</p>\n<p style=\"margin-top:12px\"><strong>E. FALSE</strong> — The proposed mechanism of neuroprotection is the opposite of what''s stated — ketamine''s NMDA receptor antagonism reduces excessive calcium influx and glutamate-mediated excitotoxicity (the process that causes neuronal injury in ischaemia/trauma), rather than increasing it; this reduction in excitotoxic calcium/glutamate activity is the proposed protective mechanism.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Ketamine Pharmacology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification & Structure</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Class</strong></td><td>Phencyclidine (PCP) derivative, arylcyclohexylamine</td></tr>\n        <tr><td><strong>Stereochemistry</strong></td><td>Chiral molecule with one stereocentre → two enantiomers (S(+) and R(-)), not geometric isomers</td></tr>\n        <tr><td><strong>Clinical preparations</strong></td><td>Racemic mixture (50:50 S:R) is standard; single-isomer S(+)-ketamine (esketamine) also available, ~2x more potent than the racemate</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mechanism of Action</div><table style=\"margin:0\"><tr><th>Target</th><th>Detail</th></tr>\n        <tr><td><strong>Primary</strong></td><td>Non-competitive (use-dependent, open-channel blocking) antagonist at the NMDA receptor, binding within the channel pore rather than the glutamate binding site</td></tr>\n        <tr><td><strong>Muscarinic ACh receptors</strong></td><td>Antagonist</td></tr>\n        <tr><td><strong>Nicotinic ACh receptors</strong></td><td>Inhibitor</td></tr>\n        <tr><td><strong>Opioid receptors</strong></td><td>Weak agonist activity — mu, kappa, sigma sites implicated</td></tr>\n        <tr><td><strong>Voltage-gated sodium channels</strong></td><td>Local anaesthetic-like membrane-stabilising effect (NOT potassium channels)</td></tr>\n        <tr><td><strong>Monoaminergic reuptake</strong></td><td>Inhibition (noradrenaline, serotonin) — central sympathomimetic basis</td></tr>\n        <tr><td><strong>Isomer differences</strong></td><td>S(+) has higher NMDA affinity and is more potent than R(-); S(+) is associated with greater psychomimetic/hallucinogenic effects; R(-) is better tolerated psychologically and of research interest (e.g. depression) for separating benefit from dissociative side effects</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cardiovascular Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Dominant effect</strong></td><td>Central sympathetic stimulation (inhibits catecholamine reuptake) → increased HR, BP, cardiac output</td></tr>\n        <tr><td><strong>Masked effect</strong></td><td>Also has a direct myocardial depressant effect, normally masked by sympathetic stimulation; unmasked in catecholamine-depleted states (critical illness, sepsis) → unexpected hypotension/reduced contractility</td></tr>\n        <tr><td><strong>QTc</strong></td><td>No significant QTc prolongation</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Respiratory Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Airway/drive</strong></td><td>Relative preservation of airway reflexes and respiratory drive compared to other anaesthetic agents</td></tr>\n        <tr><td><strong>Bronchodilation</strong></td><td>Useful in refractory status asthmaticus (via sympathomimetic + direct bronchial smooth muscle relaxation); no established isomer-specific superiority</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CNS/Neurological Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Cerebral metabolism</strong></td><td>S(+) ketamine reduces cerebral metabolic rate while preserving cerebrovascular autoregulation and CO2 reactivity (revising older teaching that ketamine universally raises ICP)</td></tr>\n        <tr><td><strong>Seizures/epilepsy</strong></td><td>Does not reliably trigger clinical seizures; used in refractory status epilepticus; not contraindicated in epilepsy</td></tr>\n        <tr><td><strong>Neuroprotection</strong></td><td>Possible neuroprotective/neuroregenerative effects — proposed mechanism is <em>reduction</em> (not increase) of excitotoxic calcium influx/glutamate activity via NMDA blockade; also implicated in synaptogenesis (BDNF/mTOR pathway — relevant to depression research)</td></tr>\n        <tr><td><strong>Clinical effects</strong></td><td>Causes dissociative anaesthesia, emergence phenomena (hallucinations, vivid dreams), nystagmus</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Renal/Urinary Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Renal failure</strong></td><td>Not contraindicated in chronic renal failure — metabolites are not a major clinical concern (unlike morphine/pethidine)</td></tr>\n        <tr><td><strong>Chronic/heavy use</strong></td><td>Causes ketamine-induced ulcerative cystitis — urinary frequency, urgency, dysuria, haematuria, reduced bladder capacity, and in severe cases hydronephrosis/renal impairment</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Immune Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Immunomodulation</strong></td><td>Anti-inflammatory properties — attenuates pro-inflammatory cytokine release (TNF-alpha, IL-6); relevance to sepsis and perioperative inflammatory response is an active research area</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Metabolism</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Pathway</strong></td><td>Hepatic, primarily via CYP3A4 (and CYP2B6) → norketamine (active metabolite, ~1/3–1/5 potency of parent)</td></tr>\n        <tr><td><strong>Excretion</strong></td><td>Renal excretion of metabolites</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_ketamine_systemic_effects_001', 'MTF', '{"dateAdded":"2026-09-04","rotationIndex":69,"stem":"Ketamine:","choices":["Ketamine has a central sympathetic effect.","Ketamine has no direct myocardial depression.","S(+) ketamine is a better choice than R(-) ketamine in treating acute asthma.","Ketamine is absolutely contraindicated in patients with chronic renal failure.","Ketamine may have immunomodulating properties."],"correct":[true,false,false,false,true],"explanation":"<p>Ketamine''s cardiovascular, respiratory, renal, and immune effects are frequently misunderstood, as its clinically observed profile (typically stimulatory) can mask underlying direct depressant actions.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> — Ketamine causes central sympathetic stimulation, via inhibition of catecholamine (noradrenaline) reuptake centrally and peripherally, which is the mechanism behind its characteristic increases in heart rate, blood pressure, and cardiac output.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> — Ketamine does have a direct myocardial depressant effect, but in most patients this is normally masked by its more dominant central sympathetic stimulation, resulting in a net stimulatory cardiovascular effect. In catecholamine-depleted states (e.g. critical illness, sepsis, chronic pain/adrenal exhaustion) where sympathetic reserve is reduced, this underlying direct depressant effect can become unmasked, causing unexpected hypotension and reduced contractility.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> — There is no clear evidence that S(+) ketamine is superior to R(-) ketamine specifically for bronchodilation in acute asthma; ketamine''s bronchodilator effect (useful in refractory status asthmaticus) is attributed to both sympathomimetic activity and direct relaxant effects on bronchial smooth muscle, but isomer-specific superiority in this indication is not established, making this statement false.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> — Ketamine is not absolutely contraindicated in chronic renal failure; its metabolites are not major clinical concerns in the way that, for example, morphine or pethidine metabolites are, and it remains a usable analgesic/anaesthetic option in renal impairment with appropriate caution and dose consideration.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> — Ketamine has been shown to have immunomodulating properties, including anti-inflammatory effects (attenuation of pro-inflammatory cytokine release such as TNF-alpha and IL-6), which is of interest in contexts such as sepsis and perioperative inflammatory response modulation, though the full clinical significance remains an area of ongoing research.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Ketamine Pharmacology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification & Structure</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Class</strong></td><td>Phencyclidine (PCP) derivative, arylcyclohexylamine</td></tr>\n        <tr><td><strong>Stereochemistry</strong></td><td>Chiral molecule with one stereocentre → two enantiomers (S(+) and R(-)), not geometric isomers</td></tr>\n        <tr><td><strong>Clinical preparations</strong></td><td>Racemic mixture (50:50 S:R) is standard; single-isomer S(+)-ketamine (esketamine) also available, ~2x more potent than the racemate</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Mechanism of Action</div><table style=\"margin:0\"><tr><th>Target</th><th>Detail</th></tr>\n        <tr><td><strong>Primary</strong></td><td>Non-competitive (use-dependent, open-channel blocking) antagonist at the NMDA receptor, binding within the channel pore rather than the glutamate binding site</td></tr>\n        <tr><td><strong>Muscarinic ACh receptors</strong></td><td>Antagonist</td></tr>\n        <tr><td><strong>Nicotinic ACh receptors</strong></td><td>Inhibitor</td></tr>\n        <tr><td><strong>Opioid receptors</strong></td><td>Weak agonist activity — mu, kappa, sigma sites implicated</td></tr>\n        <tr><td><strong>Voltage-gated sodium channels</strong></td><td>Local anaesthetic-like membrane-stabilising effect (NOT potassium channels)</td></tr>\n        <tr><td><strong>Monoaminergic reuptake</strong></td><td>Inhibition (noradrenaline, serotonin) — central sympathomimetic basis</td></tr>\n        <tr><td><strong>Isomer differences</strong></td><td>S(+) has higher NMDA affinity and is more potent than R(-); S(+) is associated with greater psychomimetic/hallucinogenic effects; R(-) is better tolerated psychologically and of research interest (e.g. depression) for separating benefit from dissociative side effects</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cardiovascular Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Dominant effect</strong></td><td>Central sympathetic stimulation (inhibits catecholamine reuptake) → increased HR, BP, cardiac output</td></tr>\n        <tr><td><strong>Masked effect</strong></td><td>Also has a direct myocardial depressant effect, normally masked by sympathetic stimulation; unmasked in catecholamine-depleted states (critical illness, sepsis) → unexpected hypotension/reduced contractility</td></tr>\n        <tr><td><strong>QTc</strong></td><td>No significant QTc prolongation</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Respiratory Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Airway/drive</strong></td><td>Relative preservation of airway reflexes and respiratory drive compared to other anaesthetic agents</td></tr>\n        <tr><td><strong>Bronchodilation</strong></td><td>Useful in refractory status asthmaticus (via sympathomimetic + direct bronchial smooth muscle relaxation); no established isomer-specific superiority</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CNS/Neurological Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Cerebral metabolism</strong></td><td>S(+) ketamine reduces cerebral metabolic rate while preserving cerebrovascular autoregulation and CO2 reactivity (revising older teaching that ketamine universally raises ICP)</td></tr>\n        <tr><td><strong>Seizures/epilepsy</strong></td><td>Does not reliably trigger clinical seizures; used in refractory status epilepticus; not contraindicated in epilepsy</td></tr>\n        <tr><td><strong>Neuroprotection</strong></td><td>Possible neuroprotective/neuroregenerative effects — proposed mechanism is <em>reduction</em> (not increase) of excitotoxic calcium influx/glutamate activity via NMDA blockade; also implicated in synaptogenesis (BDNF/mTOR pathway — relevant to depression research)</td></tr>\n        <tr><td><strong>Clinical effects</strong></td><td>Causes dissociative anaesthesia, emergence phenomena (hallucinations, vivid dreams), nystagmus</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Renal/Urinary Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Renal failure</strong></td><td>Not contraindicated in chronic renal failure — metabolites are not a major clinical concern (unlike morphine/pethidine)</td></tr>\n        <tr><td><strong>Chronic/heavy use</strong></td><td>Causes ketamine-induced ulcerative cystitis — urinary frequency, urgency, dysuria, haematuria, reduced bladder capacity, and in severe cases hydronephrosis/renal impairment</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Immune Effects</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Immunomodulation</strong></td><td>Anti-inflammatory properties — attenuates pro-inflammatory cytokine release (TNF-alpha, IL-6); relevance to sepsis and perioperative inflammatory response is an active research area</td></tr>\n        </table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Metabolism</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr>\n        <tr><td><strong>Pathway</strong></td><td>Hepatic, primarily via CYP3A4 (and CYP2B6) → norketamine (active metabolite, ~1/3–1/5 potency of parent)</td></tr>\n        <tr><td><strong>Excretion</strong></td><td>Renal excretion of metabolites</td></tr>\n        </table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;

